import { describe, expect, it } from 'vitest';
import { applySmoothing, SMOOTHING_MODES, type SmoothingMode } from './smoothing';

const fixtureFrequencies = Array.from({ length: 161 }, (_, index) => 100 * Math.pow(100, index / 160));
const fixtureValues = fixtureFrequencies.map((_, index) => (
  index === 57 || index === 99 ? null : 7 * Math.sin(index * .37) + 3 * Math.cos(index * .11) - index * .015
));
const sampleIndices = [0, 20, 40, 80, 120, 160];

// Generated by ../Waveguide Generator/src/results/smoothing.js. These values
// intentionally lock all eleven public mode IDs to the v1 oracle.
const v1Golden: Record<SmoothingMode, Array<number | null>> = {
  none: [3, 4.225453318915351, 3.995765861691956, -10.424019178135264, 3.4572850088087037, 1.8432207990104366],
  '1/1': [5.7379094141307405, -1.346758499400347, -0.9941683997712195, -3.698708460141345, 0.4157711352646571, 0.6011403217205449],
  '1/2': [6.540749208771353, 1.6754792967476275, 1.7312530015245708, -7.477929994297836, 2.162890559200863, 3.2829544724533353],
  '1/3': [5.675529098841535, 2.916285125553419, 2.83456214197076, -8.921231026762685, 2.7999583551210914, 3.30206662181122],
  '1/6': [4.2337822807319, 3.8461839941667506, 3.6595979269855947, -9.990290109935426, 3.268065215284541, 2.6495017617979952],
  '1/12': [3.301392271668156, 4.136086384120905, 3.916567296323388, -10.321905971141835, 3.4127630352071736, 2.049147794918439],
  '1/24': [3, 4.225453318915351, 3.995765861691956, -10.424019178135264, 3.4572850088087037, 1.8432207990104366],
  '1/48': [3, 4.225453318915351, 3.995765861691956, -10.424019178135264, 3.4572850088087037, 1.8432207990104366],
  variable: [3, 4.225453318915351, 3.995765861691956, -10.321905971141835, 3.268065215284541, 3.30206662181122],
  psychoacoustic: [6.491670866316626, 3.806529566800342, 3.9843030327348736, -10.073878357805457, 4.118047518272072, 2.9812260677304656],
  erb: [6.442647917344022, 2.7549826998823286, 3.3004004180122326, -9.879154363105707, 3.031598332874172, 2.475680455064878],
};

describe('v1 smoothing goldens', () => {
  it.each(SMOOTHING_MODES)('matches the %s oracle fixture', (mode) => {
    const actual = sampleIndices.map((index) => applySmoothing(fixtureFrequencies, fixtureValues, mode)[index]);
    actual.forEach((value, index) => {
      if (value === null) expect(value).toBe(v1Golden[mode][index]);
      else expect(value).toBeCloseTo(Number(v1Golden[mode][index]), 12);
    });
  });

  it('preserves the input reference for none and length mismatch', () => {
    expect(applySmoothing([100], fixtureValues, '1/3')).toBe(fixtureValues);
    expect(applySmoothing(fixtureFrequencies, fixtureValues, 'none')).toBe(fixtureValues);
  });
});
